CREATE TABLE marketplace."EmailDelivery"(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),notification_id uuid NOT NULL UNIQUE REFERENCES marketplace."Notification"(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','processing','sent','failed')),attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),claimed_at timestamptz,sent_at timestamptz);
ALTER TABLE marketplace."EmailDelivery" ENABLE ROW LEVEL SECURITY;
CREATE POLICY worker_access ON marketplace."EmailDelivery" FOR ALL TO PUBLIC USING(current_user='convyn_app') WITH CHECK(current_user='convyn_app');
DO $$ BEGIN IF EXISTS(SELECT FROM pg_roles WHERE rolname='convyn_app') THEN GRANT SELECT,INSERT,UPDATE,DELETE ON marketplace."EmailDelivery" TO convyn_app; END IF; END $$;
CREATE FUNCTION marketplace.queue_email() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,marketplace AS $$ BEGIN IF current_setting('convyn.email_enabled',true)='true' THEN INSERT INTO marketplace."EmailDelivery"(notification_id) VALUES(NEW.id) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER queue_email AFTER INSERT ON marketplace."Notification" FOR EACH ROW EXECUTE FUNCTION marketplace.queue_email();
CREATE FUNCTION marketplace.notify_request_cancel() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,marketplace AS $$ DECLARE recipient record; BEGIN IF NEW.status='cancelled' AND OLD.status<>'cancelled' THEN FOR recipient IN SELECT DISTINCT provider_user_email FROM marketplace."Bid" WHERE request_id=NEW.id LOOP PERFORM marketplace.notify(recipient.provider_user_email,'Request cancelled',NEW.reference||' was cancelled.','request','/provider'); END LOOP; END IF; RETURN NEW; END $$;
CREATE TRIGGER notify_cancel AFTER UPDATE ON marketplace."ServiceRequest" FOR EACH ROW EXECUTE FUNCTION marketplace.notify_request_cancel();
CREATE FUNCTION marketplace.expire_quotes() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,marketplace AS $$ DECLARE b record; changed integer=0; BEGIN FOR b IN UPDATE marketplace."Bid" SET status='expired' WHERE status='submitted' AND valid_until<=now() RETURNING * LOOP UPDATE marketplace."ServiceRequest" SET bid_count=(SELECT count(*) FROM marketplace."Bid" WHERE request_id=b.request_id AND status='submitted') WHERE id=b.request_id; PERFORM marketplace.notify(b.provider_user_email,'Quote expired',b.request_reference||': your quote has expired.','quote','/provider'); PERFORM marketplace.notify((SELECT customer_email FROM marketplace."ServiceRequest" WHERE id=b.request_id),'Quote expired',b.provider_name||'’s quote has expired.','quote','/requests/'||b.request_id); changed=changed+1; END LOOP; RETURN changed; END $$;
REVOKE ALL ON FUNCTION marketplace.expire_quotes() FROM PUBLIC;
DO $$ BEGIN IF EXISTS(SELECT FROM pg_roles WHERE rolname='convyn_app') THEN GRANT EXECUTE ON FUNCTION marketplace.expire_quotes() TO convyn_app; END IF; END $$;
CREATE FUNCTION marketplace.broadcast_message(input jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,marketplace,public AS $$ DECLARE count_sent integer; BEGIN IF NOT marketplace.is_admin() THEN RAISE EXCEPTION 'Administrator access required' USING ERRCODE='42501'; END IF; INSERT INTO marketplace."Notification"(created_by_id,user_email,title,body,type,link) SELECT marketplace.actor_id(),email,input->>'title',input->>'body','message',input->>'link' FROM public."User" WHERE input->>'recipient'='all' OR email=input->>'recipient'; GET DIAGNOSTICS count_sent=ROW_COUNT; IF count_sent=0 THEN RAISE EXCEPTION 'Recipient not found' USING ERRCODE='23514'; END IF; PERFORM marketplace.audit('message','Notification',NULL,jsonb_build_object('sent',count_sent)); RETURN count_sent; END $$;
REVOKE ALL ON FUNCTION marketplace.broadcast_message(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION marketplace.broadcast_message(jsonb) TO convyn_marketplace;
REVOKE ALL ON FUNCTION marketplace.queue_email(),marketplace.notify_request_cancel() FROM PUBLIC;
CREATE POLICY delivery_worker_read ON marketplace."Notification" FOR SELECT TO PUBLIC USING(current_user='convyn_app');
